    self.bit_reader.reset();
    let len = self.bit_reader.as_inner_mut().read_u16::<LittleEndian>()?;
    let nlen = self.bit_reader.as_inner_mut().read_u16::<LittleEndian>()?;
    if !len != nlen {
        Err(invalid_data_error!(
            "LEN={} is not the one's complement of NLEN={}",
            len,
            nlen
