    } else {
        let old_len = self.buffer.len();
        self.buffer.reserve(len as usize);
        unsafe { self.buffer.set_len(old_len + len as usize) };
        self.bit_reader
            .as_inner_mut()
            .read_exact(&mut self.buffer[old_len..])?;
        Ok(())
    }
