                        let mut sa6 = std::mem::zeroed();
                        *(&mut sa6 as *mut _ as *mut _) = addr;
                        sa6
                    }
                    SocketAddr::V6(addr) => *(&addr as *const _ as *const _),
                }
            },
        }
    }
}

