    where F: FnMut(char) -> bool
    {
        // literal copy-paste of std,so if this is wrong std is wrong.

        let len = self.len();
        let mut del_bytes = 0;
        let mut idx = 0;

        while idx < len {
            let ch = unsafe {
                self.get_unchecked(idx..len).chars().next().unwrap()
            };
