        impl<T, U, F> MapArray<[T; $size], F> for [U; $size]
        where
            F: FnMut(T) -> U,
        {
            fn map_array(mut values: [T; $size], mut f: F) -> Self {
                use std::{
                    mem::forget,
                    ptr::{read, write},
                };

                unsafe {
                    // All elements of `result` is written.
                    // Each element of `values` read once and then forgotten.
                    // Hence safe in case `f` never panics.
