        let core_prover = C::CoreProver::new(core_machine);

        let compress_machine = CompressAir::machine(InnerSC::default());
        let compress_prover = C::CompressProver::new(compress_machine);

        let shrink_machine = ShrinkAir::wrap_machine_dyn(InnerSC::compressed());
        let shrink_prover = C::ShrinkProver::new(shrink_machine);

        let wrap_machine = WrapAir::wrap_machine(OuterSC::default());
        let wrap_prover = C::WrapProver::new(wrap_machine);

        Self {
            recursion_program: OnceLock::new(),
            recursion_keys: OnceLock::new(),
            deferred_program: OnceLock::new(),
            deferred_keys: OnceLock::new(),
            compress_program: OnceLock::new(),
            compress_keys: OnceLock::new(),
            shrink_program: OnceLock::new(),
            shrink_keys: OnceLock::new(),
            wrap_program: OnceLock::new(),
            wrap_keys: OnceLock::new(),
            core_prover,
            compress_prover,
            shrink_prover,
            wrap_prover,
        }

            } else {
                if !allocate {
                    return false;
                }
                // calculate offset
                let off = (self.ptr.as_ptr() as usize) - (v.as_ptr() as usize);

                // new_cap is calculated in terms of `BytesMut`, not the underlying
                // `Vec`, so it does not take the offset into account.
                //
                // Thus we have to manually add it here.
                new_cap = new_cap.checked_add(off).expect("overflow");

                // The vector capacity is not sufficient. The reserve request is
                // asking for more than the initial buffer capacity. Allocate more
                // than requested if `new_cap` is not much bigger than the current
                // capacity.
                //
                // There are some situations, using `reserve_exact` that the
                // buffer capacity could be below `original_capacity`, so do a
                // check.
                let double = v.capacity().checked_shl(1).unwrap_or(new_cap);

                new_cap = cmp::max(double, new_cap);

                // No space - allocate more
                //
                // The length field of `Shared::vec` is not used by the `BytesMut`;
                // instead we use the `len` field in the `BytesMut` itself. However,
                // when calling `reserve`, it doesn't guarantee that data stored in
                // the unused capacity of the vector is copied over to the new
                // allocation, so we need to ensure that we don't have any data we
                // care about in the unused capacity before calling `reserve`.
                debug_assert!(off + len <= v.capacity());
                v.set_len(off + len);
                v.reserve(new_cap - v.len());

                // Update the info
                self.ptr = vptr(v.as_mut_ptr().add(off));
                self.cap = v.capacity() - off;
            }

            return true;
        }
    }
    if !allocate {
        return false;
    }

    let original_capacity_repr = unsafe { (*shared).original_capacity_repr };
    let original_capacity = original_capacity_from_repr(original_capacity_repr);

    new_cap = cmp::max(new_cap, original_capacity);

    // Create a new vector to store the data
    let mut v = ManuallyDrop::new(Vec::with_capacity(new_cap));

    // Copy the bytes
    v.extend_from_slice(self.as_ref());

    // Release the shared handle. This must be done *after* the bytes are
    // copied.
    unsafe { release_shared(shared) };

    // Update self
    let data = (original_capacity_repr << ORIGINAL_CAPACITY_OFFSET) | KIND_VEC;
    self.data = invalid_ptr(data);
    self.ptr = vptr(v.as_mut_ptr());
    self.cap = v.capacity();
    debug_assert_eq!(self.len, v.len());
    true
}

