impl<'a, R: RawMutex + 'a, T: ?Sized + 'a> MappedMutexGuard<'a, R, T> {
    /// Makes a new `MappedMutexGuard` for a component of the locked data.
    ///
    /// This operation cannot fail as the `MappedMutexGuard` passed
    /// in already locked the mutex.
    ///
    /// This is an associated function that needs to be
    /// used as `MappedMutexGuard::map(...)`. A method would interfere with methods of
    /// the same name on the contents of the locked data.
    #[inline]
    pub fn map<U: ?Sized, F>(s: Self, f: F) -> MappedMutexGuard<'a, R, U>
    where
        F: FnOnce(&mut T) -> &mut U,
    {
        let raw = s.raw;
        let data = f(unsafe { &mut *s.data });
        mem::forget(s);
        MappedMutexGuard {
            raw,
            data,
            marker: PhantomData,
        }
    }

    /// Attempts to make a new `MappedMutexGuard` for a component of the
    /// locked data. The original guard is returned if the closure returns `None`.
    ///
    /// This operation cannot fail as the `MappedMutexGuard` passed
    /// in already locked the mutex.

            bail!("Shortcut MUST ends with a colon (':').");
        }

        if shortcut.len() < 2 {
            bail!("Shortcut MUST be at least 2 chars to not be confused with DOS drive letters.");
        }

        if !fullname.ends_with(':') && !fullname.ends_with('/') {
            bail!("Fullname must end in a '/' (dir) or ':' (other shortcut).");
        }

        self.registry.insert(shortcut, fullname);
        Ok(())
    }

    /// Checks if a shortcut exists.
    #[inline]
    pub fn has<T: AsRef<str>>(&self, shortcut: T) -> bool {
        self.registry.contains_key(shortcut.as_ref())
    }

    /// Resolve shortcuts in the provided string recursively and return None if not exists.
    pub fn resolve<T: AsRef<str>>(&self, src: T) -> Option<String> {
        unsafe {
            let mut dst = src.as_ref().to_string();
            loop {
                // find schema letters.
                if dst.find("://").is_some() {
                    break;
                }

                if let Some(index) = dst.find(':') {
                    // ignore DOS drive letters.
                    if let Some(fullname) = self.registry.get(dst.get_unchecked(0..index + 1)) {
                        dst.replace_range(0..index + 1, fullname);
                    } else {
                        return None;
                    }
                } else {
                    break;
                }
            }

            Some(dst)
        }
    }
}

