/// thieves can take from the top of the deque while the main worker manages the bottom
/// of the deque. This deque is managed by the `scheduler` module.
pub trait Job {
    /// Unsafe: this may be called from a different thread than the one which scheduled
    /// the job, so the implementer must ensure the appropriate traits are met, whether
    /// `Send`, `Sync`, or both.
    unsafe fn execute(this: *const Self);
}

/// Effectively a Job trait object. Each JobRef **must** be executed exactly once, or
/// else data may leak.
///
/// Internally, we store the job's data in a `*const ()` pointer.  The true type is something
/// like `*const StackJob<...>`, but we hide it. We also carry the "execute fn" from the
/// `Job` trait.
#[derive(Copy, Clone, Debug, PartialEq, Eq)]
pub struct JobRef {
    pointer: *const (),
    execute_fn: unsafe fn(*const ()),
}

unsafe impl Send for JobRef {}
unsafe impl Sync for JobRef {}

impl JobRef {
    /// Unsafe: caller asserts that `data` will remain valid until the job is executed.
    pub unsafe fn new<T>(data: *const T) -> JobRef
    where
        T: Job,
    {
        let fn_ptr: unsafe fn(*const T) = <T as Job>::execute;

        // erase types:
        let fn_ptr: unsafe fn(*const ()) = mem::transmute(fn_ptr);
        let pointer = data as *const ();

        JobRef {
            pointer: pointer,
            execute_fn: fn_ptr,
        }
    }

    #[inline]
    pub unsafe fn execute(&self) {
        (self.execute_fn)(self.pointer)
    }
}

