impl<T> SliceDeque<T> {
    /// Creates a new empty deque.
    ///
    /// # Examples
    ///
    /// ```rust
    /// # use slice_deque::SliceDeque;
    /// let deq = SliceDeque::new();
    /// # let o: SliceDeque<u32> = deq;
    /// ```
    #[inline]
    pub fn new() -> Self {
        Self {
            head_: 0,
            tail_: 0,
            buf: Buffer::new(),
        }
    }

    /// Creates a SliceDeque from its raw components.
    ///
    /// The `ptr` must be a pointer to the beginning of the memory buffer from
    /// another `SliceDeque`, and `capacity` the capacity of this `SliceDeque`.
    #[inline]
    pub unsafe fn from_raw_parts(
        ptr: *mut T, capacity: usize, head: usize, tail: usize,
    ) -> Self {
        debug_assert!(head <= tail);

        let d = Self {
            head_: head,
            tail_: tail,
            buf: Buffer::from_raw_parts(ptr, capacity * 2),
        };

        debug_assert!(d.tail() <= d.tail_upper_bound());
        debug_assert!(d.head() <= d.head_upper_bound());

        d
    }

    /// Create an empty deque with capacity to hold `n` elements.
    ///
    /// # Examples
    ///
    /// ```rust
    /// # use slice_deque::SliceDeque;
    /// let deq = SliceDeque::with_capacity(10);
    /// # let o: SliceDeque<u32> = deq;
    /// ```
    #[inline]
    pub fn with_capacity(n: usize) -> Self {
        unsafe {
            Self {
                head_: 0,
                tail_: 0,
                buf: Buffer::uninitialized(2 * n).unwrap_or_else(|e| {
                    let s = tiny_str!(
                        "failed to allocate a buffer with capacity \"{}\" due to \"{:?}\"",
                        n, e
                    );
                    panic!("{}", s.as_str())
                }),
            }
        }
    }

    /// Returns the number of elements that the deque can hold without
    /// reallocating.
    ///
    /// # Examples
    ///

/// # let lock = Slock::new(User {name: "bobs"});
/// # async {
/// let name = lock.map(|v| v.name).await;
/// # };
/// ```
pub async fn map<F, U>(&self, mapper: F) -> Result<U, TimeoutError>
where
    F: FnOnce(&T) -> U,
{
    match self.lock.read() {
        Ok(v) => {
            timeout(std::time::Duration::from_secs(1), async {
                mapper(&v.value)
            })
            .await
        }
        Err(_) => panic!("Slock could not read for map!"),
    }
}

/// A setter for changing the internal data of the lock.
/// ```rust
/// # use slock::*;
/// # let lock = Slock::new(1i32);
/// # async {
/// lock.set(|v| v + 1).await;
/// lock.set(|_| 6).await;
/// # };
/// ```
pub async fn set<F>(&self, setter: F)
where
    F: FnOnce(T) -> T,
{
    match self.lock.write() {
        Ok(mut data) => {
            let ptr = &mut data.value as *mut T;
            unsafe {
                let new = timeout(std::time::Duration::from_secs(1), async {
                    setter(ptr.read())
                })
                .await;
                if let Ok(new) = new {
                    timeout(std::time::Duration::from_secs(1), async {
                        data.hook.as_mut().map(|hook| hook(&new));
                    })
                    .await
                    .ok();
                    ptr.write(new);
                }
            }
            data.version += 1;
        }
        Err(_) => panic!("Slock could not write!"),
    }
}

