macro_rules! impl_array {
    ($size:tt) => {
        impl<T, U, F> MapArray<[T; $size], F> for [U; $size]
        where
            F: FnMut(T) -> U,
        {
            fn map_array(values: [T; $size], mut f: F) -> Self {
                struct ArrayProcess<T, U> {
                    counter: usize,
                    input: std::mem::ManuallyDrop<[T; $size]>,
                    output: std::mem::ManuallyDrop<[U; $size]>,
                }

                impl<T, U> Drop for ArrayProcess<T, U> {
                    fn drop(&mut self) {
                        for i in 0 .. self.counter {
                            unsafe { std::ptr::drop_in_place(&mut self.output[i]) }
                        }

                        for i in self.counter + 1 .. $size {
                            unsafe { std::ptr::drop_in_place(&mut self.input[i]) }
                        }
                    }
                }

                unsafe {
                    let mut process = ArrayProcess::<T, U> {
                        counter: 0,
                        input: std::mem::ManuallyDrop::new(values),
                        output: std::mem::ManuallyDrop::new(std::mem::uninitialized()),
                    };

                    for i in 0 .. $size {
                        std::ptr::write(&mut process.output[i], f(std::ptr::read(&mut process.input[i])));
                        process.counter = i + 1;
                    }

                    let result = std::ptr::read(&mut *process.output);
                    std::mem::forget(process);
                    result
                }
            }
        }

        unsafe impl<T> AsStd140 for [T; $size]
        where
            T: AsStd140,
            T::Std140: Sized,
        {
            type Align = Align16;
            type Std140 = [Element<T::Std140>; $size];

            fn std140(&self) -> [Element<T::Std140>; $size] {
                struct ArrayInit<T: AsStd140> where T::Std140: Sized {
                    counter: usize,
                    output: std::mem::ManuallyDrop<[Element<T::Std140>; $size]>,
                }

                impl<T: AsStd140> Drop for ArrayInit<T> where T::Std140: Sized {
                    fn drop(&mut self) {
                        for i in 0 .. self.counter {
                            unsafe { std::ptr::drop_in_place(&mut self.output[i]) }
                        }
                    }
                }

                unsafe {
                    let mut init = ArrayInit::<T> {
                        counter: 0,
                        output: std::mem::ManuallyDrop::new(std::mem::uninitialized()),
                    };

                    for i in 0 .. $size {
                        std::ptr::write(&mut init.output[i], self[i].std140().into());
                        init.counter = i + 1;
                    }

                    let result = std::ptr::read(&mut *init.output);
                    std::mem::forget(init);
                    result
                }
            }
        }

        unsafe impl<T> AsStd140 for [Element<T>; $size]
        where
            T: AsStd140,
            T::Std140: Sized,
        {
            type Align = Align16;
            type Std140 = [Element<T::Std140>; $size];

            fn std140(&self) -> [Element<T::Std140>; $size] {
                struct ArrayInit<T: AsStd140> where T::Std140: Sized {
                    counter: usize,
                    array: std::mem::ManuallyDrop<[Element<T::Std140>; $size]>,
                }

                impl<T: AsStd140> Drop for ArrayInit<T> where T::Std140: Sized {
                    fn drop(&mut self) {
                        for i in 0 .. self.counter {
                            unsafe { std::ptr::drop_in_place(&mut self.array[i]) }
                        }
                    }
                }

                unsafe {
                    let mut init = ArrayInit::<T> {
                        counter: 0,
                        array: std::mem::ManuallyDrop::new(std::mem::uninitialized()),
                    };

                    for i in 0 .. $size {
                        std::ptr::write(&mut init.array[i], self[i].0.std140().into());
                        init.counter = i + 1;
                    }

                    let result = std::ptr::read(&mut *init.array);
                    std::mem::forget(init);
                    result
                }
            }
        }

        unsafe impl<T> Std140 for [Element<T>; $size]
        where
            T: Std140,
        {}
    };
