    /// and .
    pub fn get_aux<T: 'static>(&self, arg: c_int) -> Result<Option<&T>> {
        let p = unsafe { ffi::sqlite3_get_auxdata(self.ctx, arg) as *mut (std::any::TypeId, T) };
        if p.is_null() {
            Ok(None)
        } else {
            let id_val = unsafe { &*p };
            if std::any::TypeId::of::<T>() != id_val.0 {
                Err(Error::GetAuxWrongType)
            } else {
                Ok(Some(&id_val.1))
