        xClose: Some(rust_close::<T::Cursor>),
        xFilter: Some(rust_filter::<T::Cursor>),
        xNext: Some(rust_next::<T::Cursor>),
        xEof: Some(rust_eof::<T::Cursor>),
        xColumn: Some(rust_column::<T::Cursor>),
        xRowid: Some(rust_rowid::<T::Cursor>),
        xUpdate: None,
        xBegin: None,
        xSync: None,
        xCommit: None,
        xRollback: None,
        xFindFunction: None,
        xRename: None,
        xSavepoint: None,
        xRelease: None,
        xRollbackTo: None,
